package com.nequard.network;
import com.nequard.auth.OrganizationAccessService;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/services") public class ServiceMonitorController{private final ServiceMonitorRepository repo;private final DeviceRepository devices;private final OrganizationAccessService access;public ServiceMonitorController(ServiceMonitorRepository r,DeviceRepository d,OrganizationAccessService a){repo=r;devices=d;access=a;}@GetMapping("/device/{deviceId}")public ResponseEntity<?> byDevice(Authentication a,@PathVariable UUID deviceId){return devices.findById(deviceId).filter(d->access.canAccess(a,d.getOrganizationId())).map(d->ResponseEntity.ok(repo.findByDeviceId(deviceId))).orElse(ResponseEntity.notFound().build());}@PostMapping @PreAuthorize("hasAnyRole('SUPER_ADMIN','NETWORK_ADMIN','NETWORK_ENGINEER')")public ResponseEntity<?> create(Authentication a,@RequestBody ServiceMonitor s){return devices.findById(s.getDeviceId()).filter(d->access.canAccess(a,d.getOrganizationId())).map(d->ResponseEntity.status(201).body(repo.save(s))).orElse(ResponseEntity.notFound().build());}}